<?php
/**
 * AT指令百科 — 扩展指令数据
 * 每条: [chip_type, command, title, description, syntax, parameters, response, example, category]
 */

function _cmd($chip, $cmd, $title, $desc, $syntax, $params, $resp, $ex, $cat) {
    return [$chip, $cmd, $title, $desc, $syntax, $params, $resp, $ex, $cat];
}

