// ===== 汇总：所有扩展AT指令 =====

function getAllExtraATCommands() {
    $cmds = [];
    // 标准3GPP指令（蜂窝平台通用）
    foreach (['zte','asr','unisoc','qualcomm','eigencomm','mediatek','hisilicon','xinyi'] as $chip) {
        $cmds = array_merge($cmds, getStandard3GPPCommands($chip));
    }
    // 各平台专有指令
    $cmds = array_merge($cmds, getZTESpecificCommands());
    $cmds = array_merge($cmds, getZTECPECommands());
    $cmds = array_merge($cmds, getASRSpecificCommands());
    $cmds = array_merge($cmds, getASRCPECommands());
    $cmds = array_merge($cmds, getUnisocSpecificCommands());
    $cmds = array_merge($cmds, getUnisocCPECommands());
    $cmds = array_merge($cmds, getQualcommSpecificCommands());
    $cmds = array_merge($cmds, getESP32SpecificCommands());
    $cmds = array_merge($cmds, getSTM32SpecificCommands());
    $cmds = array_merge($cmds, getEigencommSpecificCommands());
    $cmds = array_merge($cmds, getMediaTekSpecificCommands());
    $cmds = array_merge($cmds, getHiSiliconSpecificCommands());
    $cmds = array_merge($cmds, getXinyiSpecificCommands());
    return $cmds;
}
